INSERT INTO rooms(name,type,guests,beds,price,image,tag,description,features)
SELECT (CASE WHEN t.type='Sencilla' AND t.idx=1 THEN t.name ELSE t.type||' '||t.name END),t.type,t.guests,t.beds,t.base+(t.idx-1)*120,t.image,'Disponible',t.description,t.features
FROM (SELECT 'Suite'::text AS type,2 AS guests,'1 cama king'::text AS beds,4380 AS base,'https://images.unsplash.com/photo-1774423864869-702b21c2490a?auto=format&fit=crop&w=1200&q=85'::text AS image,'Suite con terraza privada frente al Pacífico'::text AS description,ARRAY['Vista directa al mar','Desayuno incluido','Terraza privada']::text[] AS features,unnest(ARRAY['Mar Abierto','Punta Cometa','Luz del Pacífico','Horizonte']) AS name,generate_subscripts(ARRAY['Mar Abierto','Punta Cometa','Luz del Pacífico','Horizonte'],1) AS idx
UNION ALL SELECT 'Doble',4,'2 camas queen',3250,'https://images.unsplash.com/photo-1765421617367-4b6f88423be9?auto=format&fit=crop&w=1200&q=85','Habitación doble rodeada de vegetación',ARRAY['Vista al jardín','Desayuno incluido','Aire acondicionado'],unnest(ARRAY['Mangle','Palma Real','Ceiba','Cacao']),generate_subscripts(ARRAY['Mangle','Palma Real','Ceiba','Cacao'],1)
UNION ALL SELECT 'Sencilla',2,'1 cama queen',2480,'https://images.unsplash.com/photo-1743805024402-ca2e66e993c7?auto=format&fit=crop&w=1200&q=85','Habitación íntima cerca de la playa',ARRAY['Cerca de la playa','Desayuno incluido','Balcón'],unnest(ARRAY['Nido Arena','Caracola','Salina','Estrella']),generate_subscripts(ARRAY['Nido Arena','Caracola','Salina','Estrella'],1)) t
ON CONFLICT(name) DO NOTHING;
